@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : date[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class SecondHandArticle {
  + RFIDTag : string
  + Description : string
  + Category : ItemCategory
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : ItemCategory[]
}

abstract class Employee {
  + FirstName : string
  + LastName : string
}

class H2SEmployee {}

class DeliveryDriver {}

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... (other categories)
}

Resident "1" -- "*" PickupVehicle : schedules pickup for
PickupVehicle "0..*" VolunteerDriver : assigned to
VolunteerDriver "1" -- "*" DistributionCenter : delivers items to
DistributionCenter "1" -- "*" SecondHandArticle : receives and examines
H2SEmployee "1" -- "*" SecondHandArticle : assigns category to
Client "1" -- "*" H2SEmployee : requests delivery for
H2SEmployee "0..*" DeliveryDriver : arranges delivery with

@enduml

